root = 0
for v in range(1, n + 1):
    if par[v - 1] == 0:
        root = v
    else:
        kids[par[v - 1]].append(v)
order = [root]
for v in order:
    order.extend(kids[v])
size = [1] * (n + 1)
for v in reversed(order):
    if par[v - 1] != 0:
        size[par[v - 1]] += size[v]
tin = [0] * (n + 1)
timer = 0
stack = [root]
while stack:
    v = stack.pop()
    timer += 1
    tin[v] = timer
    stack.extend(kids[v])
bit = [0] * (n + 1)

def update(pos, delta):
    while pos <= n:
        bit[pos] += delta
        pos += pos & -pos

def prefix(pos):
    total = 0
    while pos > 0:
        total += bit[pos]
        pos -= pos & -pos
    return total

for v in range(1, n + 1):
    update(tin[v], vals[v - 1])
out = []
for kind, a, b in ops:
    v = int(a)
    if kind == "add":
        update(tin[v], int(b))
    else:
        out.append(prefix(tin[v] + size[v] - 1) - prefix(tin[v] - 1))
